import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import AdminPage from "./pages/AdminPage";
import HomePage from "./pages/HomePage";
import MerchantOnboarding from "./components/MerchantOnboarding";
import Login from "./components/Login";
import AcceptOrder from "./components/AcceptOrder";
import MarkOrderReady from "./components/MarkOrderReady";
import CollectOrder from "./components/CollectOrder";
import NewInventory from "./components/NewInventory";
import ModifyInventory from "./components/ModifyInventory";
import Logout from "./components/Logout";
import ViewUsers from "./components/ViewUsers";
import SignUp from "./components/SignUp"; // Ensure this import is included

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/admin" element={<AdminPage />} />
          <Route path="/onboarding" element={<MerchantOnboarding />} />
          <Route path="/login-merchant" element={<Login role="M" />} />
          <Route path="/login-admin" element={<Login role="SA" />} />
          <Route path="/sign-up" element={<SignUp />} /> {/* Add this line */}
          <Route path="/accept-order" element={<AcceptOrder />} />
          <Route path="/mark-ready" element={<MarkOrderReady />} />
          <Route path="/collect-order" element={<CollectOrder />} />
          <Route path="/new-inventory" element={<NewInventory />} />
          <Route
            path="/increase-inventory"
            element={<ModifyInventory type="increase" />}
          />
          <Route
            path="/decrease-inventory"
            element={<ModifyInventory type="decrease" />}
          />
          <Route path="/logout" element={<Logout />} />
          <Route
            path="/view-customers"
            element={<ViewUsers type="customers" />}
          />
          <Route
            path="/view-merchants"
            element={<ViewUsers type="merchants" />}
          />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
